const rows = msg.payload;
const n = 3;
let best = null;
for (let i = 0; i + n <= rows.length; i++) {
  const w = rows.slice(i, i + n);
  if (w.some((r, j) => j > 0 && r.start !== w[j - 1].end)) continue;
  const avg = w.reduce((a, r) => a + r.price, 0) / n;
  if (!best || avg < best.avg) best = { avg, start: w[0].start, end: w[n - 1].end, forecast: w.some(r => r.type === 'forecast') };
}
msg.payload = best;
return msg;
